import {PHARMACOLOGY} from './pharmacology-data.js';
import {illustrativeAP,defaultAPMode,apPhase,PHARM_DURATION} from './pharmacology-ap.js';
import {createPharmacologyViewer} from './pharmacology-view.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=Object.fromEntries(PHARMACOLOGY.drugs.map(d=>[d.id,d]));
const cache=new Map();
const CHANNEL_DRUGS={sodium:['quinidine','procainamide','disopyramide','lidocaine','mexiletine','flecainide','propafenone'],calcium:['verapamil','diltiazem'],potassium:['dofetilide','sotalol','amiodarone','dronedarone']};
const GROUPS=[['all','All medicines'],['I','Na⁺'],['II','β receptors'],['III','Repolarization'],['IV','Ca²⁺'],['Other','Other targets']];
const category=d=>d.class==='Other'?'Other':d.class==='IV'?'IV':d.class==='II'?'II':d.class.startsWith('III')?'III':'I';
export const pharmacologyLaunch=`<button class="channel-lens-launch pharmacology-launch" id="pharmacology-open" aria-haspopup="dialog"><svg viewBox="0 0 30 30" aria-hidden="true"><path d="m9 6 15 15a5 5 0 0 1-7 7L2 13a5 5 0 0 1 7-7Z" transform="translate(2 -2) scale(.9)"/><path d="m9 17 7-7M21 4v6M18 7h6"/></svg><span><strong>Explore pharmacology</strong><small>Binding sites → action potentials</small></span><span aria-hidden="true">↗</span></button>`;

export function getPharmacologyDrug(id){return byId[id]||null;}
export function drugsForChannel(id){return(CHANNEL_DRUGS[id]||[]).map(id=>byId[id]);}
export async function loadDrugStructure(id){
 const drug=byId[id];if(!drug)return null;
 const key=drug.structure||(drug.primaryTarget==='nav'?'quinidineNav':['amiodarone','dronedarone'].includes(id)?'hERGReference':null);
 if(!key)return null;
 if(!cache.has(key))cache.set(key,fetch(new URL(`./data/pharmacology/${key}.json`,import.meta.url)).then(r=>{if(!r.ok)throw Error('Protein data unavailable');return r.json();}).catch(e=>{cache.delete(key);throw e;}));
 const source=await cache.get(key),actual=!!drug.structure&&!!source.ligand;
 let note=PHARMACOLOGY.structures[key]?.note||'';
 if(drug.primaryTarget==='nav'&&!drug.structure)note='The reference protein is quinidine-bound human NaV1.5, with quinidine hidden. The halo indicates a shared pore region; it is not an experimental pose for '+drug.name+'.';
 if(['amiodarone','dronedarone'].includes(id))note='hERG is one illustrative repolarization target. This medicine has several actions; the halo is a supported region, not an experimentally resolved drug pose.';
 return{...source,ligand:actual?source.ligand:null,drugId:id,drugName:drug.name,structureNote:note,evidence:actual?drug.bindingEvidence:'Supported binding region',actualLigand:actual,citation:{url:PHARMACOLOGY.sources[drug.sourceIds.at(-1)]||source.sourceUrl},state:actual?'Fixed experimental drug-bound snapshot':'Structural reference with a regional teaching highlight',caveat:note};
}

export function initializePharmacology({pause}={}){
 const dialog=document.createElement('dialog');dialog.id='pharmacology-dialog';dialog.setAttribute('aria-labelledby','pharm-title');
 dialog.innerHTML=`<header class="pharm-heading"><div><div class="eyebrow">OPTIONAL REFERENCE · PHARMACOLOGY</div><h2 id="pharm-title">A small molecule. <br><em>A different heartbeat.</em></h2><p>Explore the target, then follow the change in one cell’s voltage.</p></div><button class="close-btn" id="pharm-close" aria-label="Close pharmacology">×</button></header>
 <div class="pharm-body"><aside class="pharm-library" aria-label="Choose a medicine"><label for="pharm-search">FIND A MEDICINE <span>21</span></label><input id="pharm-search" type="search" placeholder="Search medicines" autocomplete="off"><div class="pharm-filters" aria-label="Filter medicine family">${GROUPS.map(([id,label])=>`<button data-pharm-group="${id}" aria-pressed="${id==='all'}">${label}</button>`).join('')}</div><div class="pharm-drug-list" id="pharm-drugs"></div><p class="pharm-library-note">Mechanisms and structural evidence.<br>No doses or treatment selection.</p></aside>
 <main class="pharm-main"><div class="pharm-drug-heading"><div><span class="pharm-class" id="pharm-class"></span><h3 id="pharm-drug-name"></h3></div><span class="pharm-evidence" id="pharm-evidence"></span></div><div class="pharm-target-grid"><section class="pharm-molecular-stage" aria-label="Medicine binding site"><div class="pharm-model-head"><span id="pharm-protein-name">Protein structure</span><a id="pharm-pdb" target="_blank" rel="noopener"></a></div><canvas id="pharm-protein" tabindex="0" role="img" aria-label="Three-dimensional protein with binding site. Drag or use arrow keys to rotate; scroll or plus and minus to zoom."></canvas><p id="pharm-loading" role="status" hidden></p><div class="pharm-model-tools"><button id="pharm-focus" aria-pressed="false">Focus binding site</button><div><button id="pharm-minus" aria-label="Zoom out of binding site">−</button><button id="pharm-plus" aria-label="Zoom into binding site">+</button><button id="pharm-reset" aria-label="Reset binding-site view">↺</button></div></div><div class="pharm-model-foot"><span id="pharm-method"></span><span>Drag to rotate · scroll to zoom</span></div></section>
 <section class="pharm-explanation"><div class="pharm-target-label">WHERE IT ACTS</div><h4 id="pharm-target"></h4><p id="pharm-summary"></p><div class="pharm-effect-card"><span>AT THE CELL</span><p id="pharm-ap-effect"></p></div><div class="pharm-effect-card"><span>ON THE ECG</span><p id="pharm-ecg-effect"></p></div><p class="pharm-structure-note" id="pharm-structure-note"></p></section></div>
 <section class="pharm-comparison" aria-labelledby="pharm-ap-title"><div class="pharm-ap-heading"><div><div class="eyebrow">FROM TARGET TO VOLTAGE</div><h4 id="pharm-ap-title">Compare action potentials.</h4></div><div class="pharm-cell-switch" aria-label="Cell type"><button data-pharm-cell="ventricular" aria-pressed="true">Ventricular</button><button data-pharm-cell="nodal" aria-pressed="false">Nodal</button></div></div><div class="pharm-ap-legend"><span><i class="baseline"></i>Baseline</span><span><i class="medicine"></i><b id="pharm-legend-name"></b></span><span class="pharm-illustrative">ILLUSTRATIVE · NOT A PATIENT PREDICTION</span></div><svg id="pharm-ap" viewBox="0 0 800 245" role="img" aria-label="Baseline and medicine-influenced action potentials on a shared time axis"><defs><linearGradient id="pharm-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#bd8852" stop-opacity=".15"/><stop offset="1" stop-color="#bd8852" stop-opacity="0"/></linearGradient></defs><g id="pharm-grid"></g><path id="pharm-ap-area" fill="url(#pharm-fill)"/><path id="pharm-baseline" fill="none" stroke="#9ba99b" stroke-width="2" stroke-dasharray="5 5"/><path id="pharm-treated" fill="none" stroke="#a87342" stroke-width="2.5"/><line id="pharm-time-line" y1="17" y2="205" stroke="#c78779" stroke-width="1.3"/><circle id="pharm-time-dot" r="4" fill="#a87342" stroke="#fbfcf5" stroke-width="2"/></svg><div class="pharm-ap-caption"><span>Membrane voltage · inside minus outside (mV)</span><span>Time (ms)</span></div><div class="pharm-comparison-controls"><button id="pharm-play" aria-label="Play action-potential comparison">▶</button><label class="pharm-time-control" for="pharm-time">Explore time<input id="pharm-time" type="range" min="0" max="800" value="150" step="1"><output id="pharm-time-readout">150 ms</output></label><label class="pharm-strength-control" for="pharm-strength">Illustrative effect<input id="pharm-strength" type="range" min="0" max="100" value="65" step="1"><span>Off → stronger</span></label></div><p class="pharm-phase-readout" id="pharm-phase-readout" aria-live="off"></p><p class="pharm-ap-note" id="pharm-ap-note">The slider illustrates a mechanism; it is not a dose or measured concentration. These curves represent one cell, not an ECG lead.</p></section>
 <details class="pharm-sources"><summary>Evidence, structural caveats & sources</summary><div id="pharm-sources-content"></div><p>Fixed experimental coordinates are simplified to resolved backbones and ligand atoms. The camera moves; the protein is not simulated. Regional highlights indicate a supported area, not a docked pose. The action potentials are qualitative teaching curves, not a validated drug-response model.</p></details></main></div>`;
 document.body.append(dialog);const $=id=>dialog.querySelector('#'+id),viewer=createPharmacologyViewer($('pharm-protein'));
 let selected='quinidine',group='all',search='',mode='ventricular',strength=.65,time=150,playing=false,raf=null,last=0,request=0,focused=false;
 const chart=$('pharm-ap'),x=t=>46+t/800*737,y=v=>205-(v+100)/150*185;
 const grid=[];for(const v of[-100,-50,0,50])grid.push(`<path d="M46 ${y(v)}H783" stroke="#dce3d4" stroke-width=".7"/><text x="36" y="${y(v)+3}" text-anchor="end">${v}</text>`);for(const t of[0,200,400,600,800])grid.push(`<path d="M${x(t)} 17V205" stroke="#e3e8dc" stroke-width=".6"/><text x="${x(t)}" y="228" text-anchor="middle">${t}</text>`);$('pharm-grid').innerHTML=grid.join('');
 function renderList(){const rows=PHARMACOLOGY.drugs.filter(d=>(group==='all'||category(d)===group)&&(d.name+' '+d.targets.join(' ')).toLowerCase().includes(search.toLowerCase()));$('pharm-drugs').innerHTML=rows.length?rows.map(d=>`<button data-pharm-drug="${d.id}" class="pharm-drug" aria-pressed="${selected===d.id}"><span>${esc(d.name)}</span><small>${esc(d.class.replace(' / multiple',''))}</small></button>`).join(''):'<p class="pharm-no-results">No matching medicine.</p>';$('pharm-drugs').querySelectorAll('[data-pharm-drug]').forEach(b=>b.onclick=()=>select(b.dataset.pharmDrug));dialog.querySelectorAll('[data-pharm-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pharmGroup===group)));}
 function path(effect){let out='';for(let t=0;t<=800;t++)out+=(t?'L':'M')+x(t).toFixed(2)+' '+y(illustrativeAP(selected,t,effect,mode)).toFixed(2);return out;}
 function drawTime(){const xx=x(time),v=illustrativeAP(selected,time,strength,mode);$('pharm-time-line').setAttribute('x1',xx);$('pharm-time-line').setAttribute('x2',xx);$('pharm-time-dot').setAttribute('cx',xx);$('pharm-time-dot').setAttribute('cy',y(v));$('pharm-time').value=Math.round(time);$('pharm-time-readout').textContent=Math.round(time)+' ms';$('pharm-phase-readout').textContent=apPhase(time,mode,selected,strength);}
 function drawAP(){const p=path(strength);$('pharm-baseline').setAttribute('d',path(0));$('pharm-treated').setAttribute('d',p);$('pharm-ap-area').setAttribute('d',p+`L${x(800)} 205L46 205Z`);$('pharm-legend-name').textContent=byId[selected].name;dialog.querySelectorAll('[data-pharm-cell]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pharmCell===mode)));let extra='';if(mode==='ventricular'&&category(byId[selected])==='II')extra=' This family mainly changes nodal pacing and sympathetic signaling, so the ventricular curves largely overlap.';if(mode==='nodal'&&category(byId[selected])==='I')extra=' Fast sodium block has a much smaller direct effect on this calcium-dependent nodal cartoon.';if(selected==='magnesium'&&mode==='ventricular')extra=' Here the baseline is deliberately prolonged and has an early afterdepolarization; magnesium reduces the oscillation without automatically shortening the entire action potential.';$('pharm-ap-note').textContent='The slider illustrates a mechanism; it is not a dose or measured concentration. These are single-cell curves, not an ECG lead.'+extra;drawTime();}
 function sourceCopy(drug,record){const structure=drug.structure?PHARMACOLOGY.structures[drug.structure]:null;return `<p>${esc(record?.structureNote||(drug.primaryTarget==='beta1'?'The receptor cartoon illustrates indirect signaling. No medicine-specific atomic binding pose is asserted here.':PHARMACOLOGY.visualConventions.modelNotice))}</p>${record?`<p>${esc(record.title)} · ${esc(record.species)} · ${esc(record.method)} · ${record.resolution} Å. ${record.actualLigand?'The medicine atoms and protein backbone share the original coordinate frame.':'The colored halo is a regional teaching marker.'}</p><a href="${esc(record.sourceUrl)}" target="_blank" rel="noopener">Experimental structure · PDB ${esc(record.pdbId)} ↗</a>`:''}<div class="pharm-source-links">${drug.sourceIds.map(id=>`<a href="${esc(PHARMACOLOGY.sources[id])}" target="_blank" rel="noopener">${id.endsWith('Label')?'Prescribing information':id.includes('Structure')?'Original structural study':id.includes('Experiment')?'Experimental evidence':'Functional binding evidence'} ↗</a>`).join('')}</div>`;}
 async function select(id){if(!byId[id])return;selected=id;const token=++request,drug=byId[id];mode=defaultAPMode(drug);time=150;focused=false;playing=false;updatePlay();renderList();$('pharm-class').textContent='CLASS '+drug.class.toUpperCase();$('pharm-drug-name').textContent=drug.name;$('pharm-target').textContent=drug.targets.join(' · ');$('pharm-summary').textContent=drug.summary;$('pharm-ap-effect').textContent=drug.apEffect;$('pharm-ecg-effect').textContent=drug.ecgEffect;$('pharm-evidence').textContent=drug.bindingEvidence;$('pharm-protein-name').textContent='Target mechanism';$('pharm-pdb').hidden=true;$('pharm-method').textContent='Schematic mechanism';$('pharm-structure-note').textContent='';$('pharm-focus').disabled=true;$('pharm-focus').setAttribute('aria-pressed','false');$('pharm-loading').hidden=false;$('pharm-loading').textContent='Loading binding-site evidence…';viewer.set(null,drug);drawAP();
  try{const record=await loadDrugStructure(id);if(token!==request)return;viewer.set(record,drug);$('pharm-loading').hidden=true;if(record){$('pharm-protein-name').textContent=record.protein;$('pharm-pdb').hidden=false;$('pharm-pdb').href=record.sourceUrl;$('pharm-pdb').textContent='PDB '+record.pdbId+' ↗';$('pharm-method').textContent=`${record.method==='X-ray diffraction'?'X-ray':'Cryo-EM'} · ${record.resolution} Å`;$('pharm-evidence').textContent=record.evidence;$('pharm-structure-note').textContent=record.structureNote;$('pharm-focus').disabled=false;}else{$('pharm-structure-note').textContent=drug.primaryTarget==='beta1'?'The drug binds a receptor. Changes in channel behavior follow through intracellular signaling.':'This mechanism is not represented by a single validated binding pose.';}$('pharm-sources-content').innerHTML=sourceCopy(drug,record);}
  catch(error){if(token!==request)return;$('pharm-loading').textContent='The structure could not load. The mechanism and action-potential comparison remain available.';$('pharm-sources-content').innerHTML=sourceCopy(drug,null);}
 }
 function updatePlay(){$('pharm-play').textContent=playing?'Ⅱ':'▶';$('pharm-play').setAttribute('aria-label',playing?'Pause action-potential comparison':'Play action-potential comparison');if(playing&&!raf){last=performance.now();raf=requestAnimationFrame(tick);}else if(!playing&&raf){cancelAnimationFrame(raf);raf=null;}}
 function tick(now){raf=null;if(!playing||!dialog.open)return;time=(time+Math.min(80,now-last)*.08)%PHARM_DURATION;last=now;drawTime();raf=requestAnimationFrame(tick);}
 function seekTime(value){time=Math.max(0,Math.min(PHARM_DURATION,value));playing=true;last=performance.now();updatePlay();drawTime();}
 $('pharm-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{playing=false;request++;updatePlay();});$('pharm-search').oninput=e=>{search=e.target.value;renderList();};dialog.querySelectorAll('[data-pharm-group]').forEach(b=>b.onclick=()=>{group=b.dataset.pharmGroup;renderList();});dialog.querySelectorAll('[data-pharm-cell]').forEach(b=>b.onclick=()=>{mode=b.dataset.pharmCell;drawAP();});$('pharm-strength').oninput=e=>{strength=+e.target.value/100;drawAP();};$('pharm-time').oninput=e=>seekTime(+e.target.value);$('pharm-play').onclick=()=>{playing=!playing;updatePlay();};
 let scrub=null;const seek=e=>{const r=chart.getBoundingClientRect();if(!r.width)return;seekTime(((e.clientX-r.left)/r.width*800-46)/737*800);};chart.addEventListener('pointerdown',e=>{if(e.button!==0)return;scrub=e.pointerId;chart.setPointerCapture(e.pointerId);seek(e);});chart.addEventListener('pointermove',e=>{if(scrub===e.pointerId)seek(e);});const end=e=>{if(scrub===e.pointerId){scrub=null;if(chart.hasPointerCapture(e.pointerId))chart.releasePointerCapture(e.pointerId);}};chart.addEventListener('pointerup',end);chart.addEventListener('pointercancel',end);
 $('pharm-focus').onclick=()=>{focused=!focused;viewer.focus(focused);$('pharm-focus').setAttribute('aria-pressed',String(focused));};$('pharm-plus').onclick=()=>viewer.zoomBy(1.2);$('pharm-minus').onclick=()=>viewer.zoomBy(1/1.2);$('pharm-reset').onclick=()=>{focused=false;viewer.reset();$('pharm-focus').setAttribute('aria-pressed','false');};
 return{open({drug='quinidine',channel=null}={}){pause?.();group=channel==='sodium'?'I':channel==='calcium'?'IV':channel==='potassium'?'III':'all';search='';$('pharm-search').value='';if(!dialog.open)dialog.showModal();select(drug);viewer.refresh();},close:()=>dialog.close(),isOpen:()=>dialog.open};
}
